        id: openCodeProjectDialog
        title: "Elegí el proyecto para OpenCode"
        onAccepted: {
            var path = selectedFolder.toString().replace("file:///", "")
            var err = App.launchOpenCode(path, openCodeProfile.currentValue ?? "")
            gwMsg.text = err.length === 0
