QJsonObject HarnessRuntimeModule::toJson() const
{
    QJsonObject o;
    o[QStringLiteral("engine")] = engine;
    o[QStringLiteral("version")] = version;
    o[QStringLiteral("fallbackEngine")] = fallbackEngine;
    o[QStringLiteral("experimental")] = experimental;
    return o;
}

